function calcAge(birthdate) {
  if (!birthdate) return "";
  const b = new Date(birthdate);
  const t = new Date();
  let age = t.getFullYear() - b.getFullYear();
  const m = t.getMonth() - b.getMonth();
  if (m < 0 || (m === 0 && t.getDate() < b.getDate())) age--;
  return age;
}

function ageGroupFromAge(age) {
  if (age === "" || age === null || age === undefined) return AGE_GROUPS[0];
  if (age <= 17) return AGE_GROUPS[0];
  if (age <= 24) return AGE_GROUPS[1];
  return AGE_GROUPS[2];
}

function daysUntilNextBirthday(birthdate) {
  if (!birthdate) return null;
  const b = new Date(birthdate);
  const t = new Date();
  let next = new Date(t.getFullYear(), b.getMonth(), b.getDate());
  if (next < t) next = new Date(t.getFullYear() + 1, b.getMonth(), b.getDate());
  return Math.ceil((next - t) / (1000 * 60 * 60 * 24));
}

function agingStatus(m) {
  if (m.age === "" || m.age === null || m.age === undefined) return null;
  if (m.age >= 31) return { level: "overage", label: "Overage — no longer eligible for KK, should be archived" };
  if (m.age === 30) return { level: "urgent", label: `Turns 31 in ${daysUntilNextBirthday(m.birthdate)} day(s) — will age out` };
  if (m.age === 29) return { level: "watch", label: "Turns 30 next birthday — one year left in KK" };
  return null;
}

function newId() { return Date.now() + "-" + Math.random().toString(36).slice(2, 7); }

