// ---------- SELF REGISTRATION (public) ----------

function SelfRegisterScreen({ onBack }) {
  const [form, setForm] = useState({ ...emptyMemberForm, verified: false, source: "self" });
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState("");
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");
  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  async function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setUploadError("");
    setUploading(true);
    try {
      const url = await storage.uploadMemberPhoto(form.barangay, file);
      setForm(f => ({ ...f, photoUrl: url }));
    } catch (err) {
      setUploadError("Could not upload photo — please try a smaller image.");
    }
    setUploading(false);
  }

  function toggleClassification(c) {
    setForm(f => {
      const has = f.classification.includes(c);
      const classification = has ? f.classification.filter(x => x !== c) : [...f.classification, c];
      const stillISY = classification.some(x => x.includes("In-School Youth"));
      return { ...f, classification, schoolName: stillISY ? f.schoolName : "", gradeLevel: stillISY ? f.gradeLevel : "", program: stillISY ? f.program : "" };
    });
  }

  async function handleSubmit(e) {
    e.preventDefault();
    if (!form.lastName.trim() || !form.firstName.trim() || !form.birthdate) {
      setError("Please fill in your name and birthdate.");
      return;
    }
    setError("");
    const age = calcAge(form.birthdate);
    const record = { ...form, age, ageGroup: ageGroupFromAge(age), id: newId(), verified: false, source: "self", archived: false };
    try {
      await storage.submitSelfRegistration(record);
      setSubmitted(true);
    } catch (e2) {
      setError("Could not submit. Please check your connection and try again.");
    }
  }

  const inputCls = "w-full rounded-lg border border-stone-300 bg-white px-3 py-2 text-sm text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#E8A93B] focus:border-transparent";
  const labelCls = "block text-xs font-semibold uppercase tracking-wide text-stone-500 mb-1";

  if (submitted) {
    return (
      <div className="min-h-screen flex items-center justify-center px-4" style={{ background: CREAM, fontFamily: "'Inter', system-ui, sans-serif" }}>
        <div className="max-w-sm w-full bg-white rounded-xl border border-stone-200 p-6 text-center">
          <CheckCircle2 size={40} style={{ color: LEAF }} className="mx-auto mb-3" />
          <h2 className="font-bold text-lg" style={{ color: NAVY }}>Profile Submitted!</h2>
          <p className="text-sm text-stone-500 mt-2">
            Thank you, {form.firstName}. Your KK profile for Barangay {form.barangay} has been received and is pending
            verification by your SK officials.
          </p>
          <button onClick={onBack} className="mt-5 w-full py-2.5 rounded-lg text-white text-sm font-semibold" style={{ background: NAVY }}>
            Back to Home
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen" style={{ background: CREAM, fontFamily: "'Inter', system-ui, sans-serif" }}>
      <header className="text-white" style={{ background: NAVY }}>
        <div className="max-w-3xl mx-auto px-5 py-4 flex items-center gap-3">
          <button onClick={onBack} className="text-stone-300 hover:text-white"><ArrowLeft size={18} /></button>
          <div>
            <h1 className="text-base font-bold">Ka-Par! — KK Youth Profile Registration</h1>
            <p className="text-xs text-stone-300">Municipality of Presentacion</p>
          </div>
        </div>
      </header>

      <main className="max-w-3xl mx-auto px-5 py-6">
        <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 p-5">
          <p className="text-sm text-stone-500 mb-4">Fill this out yourself — a member of your barangay's SK will review and verify your entry.</p>

          <div className="mb-4 flex items-center gap-4">
            <div className="w-20 h-24 rounded-lg overflow-hidden bg-stone-100 shrink-0 flex items-center justify-center">
              {form.photoUrl
                ? <img src={form.photoUrl} alt="" className="w-full h-full object-cover" />
                : <Users size={24} className="text-stone-300" />}
            </div>
            <div>
              <label className={labelCls}>Photo (for your digital ID)</label>
              <input type="file" accept="image/jpeg,image/png,image/webp" onChange={handlePhotoChange} className="text-xs" />
              {uploading && <div className="text-xs text-stone-400 mt-1">Uploading…</div>}
              {uploadError && <div className="text-xs text-red-600 mt-1">{uploadError}</div>}
            </div>
          </div>

          <div className="grid sm:grid-cols-2 gap-4 mb-4">
            <div>
              <label className={labelCls}>Barangay *</label>
              <select value={form.barangay} onChange={set("barangay")} className={inputCls}>{BARANGAYS.map(b => <option key={b}>{b}</option>)}</select>
            </div>
            <div>
              <label className={labelCls}>Sex Assigned at Birth</label>
              <select value={form.sex} onChange={set("sex")} className={inputCls}><option>Male</option><option>Female</option></select>
            </div>
          </div>

          <div className="grid sm:grid-cols-3 gap-4 mb-4">
            <div><label className={labelCls}>Last Name *</label><input required value={form.lastName} onChange={set("lastName")} className={inputCls} /></div>
            <div><label className={labelCls}>First Name *</label><input required value={form.firstName} onChange={set("firstName")} className={inputCls} /></div>
            <div><label className={labelCls}>Middle Name</label><input value={form.middleName} onChange={set("middleName")} className={inputCls} /></div>
          </div>

          <div className="grid sm:grid-cols-2 gap-4 mb-4">
            <div><label className={labelCls}>Birthdate *</label><input required type="date" value={form.birthdate} onChange={set("birthdate")} className={inputCls} /></div>
            <div>
              <label className={labelCls}>Civil Status</label>
              <select value={form.civilStatus} onChange={set("civilStatus")} className={inputCls}>{CIVIL_STATUS.map(c => <option key={c}>{c}</option>)}</select>
            </div>
          </div>

          <div className="mb-4">
            <label className={labelCls}>Which describes you? (select all that apply)</label>
            <div className="flex flex-wrap gap-2">
              {CLASSIFICATIONS.map(c => (
                <button type="button" key={c} onClick={() => toggleClassification(c)}
                  className="px-3 py-1.5 rounded-full text-xs font-medium border transition"
                  style={form.classification.includes(c) ? { background: NAVY, color: "white", borderColor: NAVY } : { background: "white", color: "#57534e", borderColor: "#d6d3d1" }}>
                  {c}
                </button>
              ))}
            </div>
            <div className="flex gap-4 mt-2">
              <label className="flex items-center gap-1.5 text-sm text-stone-600"><input type="checkbox" checked={form.pwd} onChange={e => setForm(f => ({ ...f, pwd: e.target.checked }))} /> Person with Disability</label>
              <label className="flex items-center gap-1.5 text-sm text-stone-600"><input type="checkbox" checked={form.ip} onChange={e => setForm(f => ({ ...f, ip: e.target.checked }))} /> Indigenous Person</label>
            </div>
            {form.classification.some(c => c.includes("In-School Youth")) && (
              <div className="mt-3 grid sm:grid-cols-2 gap-3">
                <div className="sm:col-span-2">
                  <label className={labelCls}>School / Institution Name</label>
                  <input value={form.schoolName} onChange={set("schoolName")} className={inputCls} placeholder="e.g. Presentacion National High School" list="school-options" />
                  <datalist id="school-options">
                    {SCHOOLS.map(s => <option key={s} value={s} />)}
                  </datalist>
                </div>
                <div>
                  <label className={labelCls}>Grade / Year Level</label>
                  <select value={form.gradeLevel} className={inputCls}
                    onChange={e => setForm(f => ({ ...f, gradeLevel: e.target.value, program: needsProgram(e.target.value) ? f.program : "" }))}>
                    <option value="">Select…</option>
                    {GRADE_LEVELS.map(g => <option key={g}>{g}</option>)}
                  </select>
                </div>
                {needsProgram(form.gradeLevel) && (
                  <div>
                    <label className={labelCls}>{form.gradeLevel.includes("College") ? "Course / Program" : "Strand"}</label>
                    <input value={form.program} onChange={set("program")} className={inputCls}
                      placeholder={form.gradeLevel.includes("College") ? "e.g. BS Computer Science" : "e.g. STEM, HUMSS, ABM"} />
                  </div>
                )}
              </div>
            )}
          </div>

          <div className="grid sm:grid-cols-2 gap-4 mb-4">
            <div><label className={labelCls}>Email Address</label><input type="email" value={form.email} onChange={set("email")} className={inputCls} /></div>
            <div><label className={labelCls}>Contact Number</label><input value={form.contact} onChange={set("contact")} className={inputCls} /></div>
          </div>

          <div className="mb-4">
            <label className={labelCls}>Home Address</label>
            <input value={form.address} onChange={set("address")} className={inputCls} placeholder="Purok/Sitio" />
          </div>

          <div className="grid sm:grid-cols-2 gap-4 mb-4">
            <div>
              <label className={labelCls}>Highest Educational Attainment</label>
              <select value={form.education} onChange={set("education")} className={inputCls}>{EDUC_ATTAINMENT.map(e => <option key={e}>{e}</option>)}</select>
            </div>
            <div>
              <label className={labelCls}>Work Status</label>
              <select value={form.workStatus} onChange={set("workStatus")} className={inputCls}>{WORK_STATUS.map(w => <option key={w}>{w}</option>)}</select>
            </div>
          </div>

          <div className="grid sm:grid-cols-3 gap-4 mb-5">
            <div><label className={labelCls}>Registered SK Voter</label><select value={form.registeredSKVoter} onChange={set("registeredSKVoter")} className={inputCls}><option>Yes</option><option>No</option></select></div>
            <div><label className={labelCls}>Registered National Voter</label><select value={form.registeredNationalVoter} onChange={set("registeredNationalVoter")} className={inputCls}><option>Yes</option><option>No</option></select></div>
            <div><label className={labelCls}>Attended a KK Assembly</label><select value={form.attendedAssembly} onChange={set("attendedAssembly")} className={inputCls}><option>Yes</option><option>No</option></select></div>
          </div>

          {error && <p className="text-xs text-red-600 mb-3">{error}</p>}

          <button type="submit" className="w-full py-2.5 rounded-lg text-white text-sm font-semibold" style={{ background: NAVY }}>Submit My Profile</button>
        </form>
      </main>
    </div>
  );
}

// ---------- LOGIN ----------

function LoginScreen({ onLogin, onBack }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [checking, setChecking] = useState(false);

  async function handleSubmit(e) {
    e.preventDefault();
    setError("");
    setChecking(true);
    try {
      const session = await auth.signIn(email, password);
      const profile = await auth.getProfile(session.user.id);
      onLogin({ role: profile.role, barangay: profile.barangay, userId: session.user.id, email: session.user.email });
    } catch (e2) {
      setError("Incorrect email or password.");
    }
    setChecking(false);
  }

  return (
    <div className="min-h-screen flex items-center justify-center px-4" style={{ background: CREAM, fontFamily: "'Inter', system-ui, sans-serif" }}>
      <div className="w-full max-w-sm">
        <button onClick={onBack} className="flex items-center gap-1 text-sm text-stone-500 mb-4"><ArrowLeft size={15} /> Back</button>
        <div className="flex flex-col items-center mb-6">
          <div className="flex items-center justify-center gap-2 mb-3 p-2 rounded-full" style={{ background: NAVY }}>
            <LogoBadge src={MUNICIPAL_LOGO_B64} label="Municipality of Presentacion" size={44} />
            <LogoBadge src={LYDC_LOGO_B64} label="LYDC" size={44} />
            <LogoBadge src={SKF_LOGO_B64} label="SK Federation" size={44} />
          </div>
          <h1 className="text-lg font-bold text-center" style={{ color: NAVY }}>Ka-Par!</h1>
          <p className="text-xs font-medium text-center" style={{ color: LEAF }}>Alamin. Iprofile. Paunlarin.</p>
          <p className="text-xs text-stone-500 text-center mt-1">LYDC &middot; Municipality of Presentacion</p>
        </div>

        <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 p-5">
          <div className="mb-3">
            <label className="block text-xs font-semibold uppercase tracking-wide text-stone-500 mb-1">Email</label>
            <input type="email" value={email} onChange={e => setEmail(e.target.value)} required
              className="w-full rounded-lg border border-stone-300 px-3 py-2 text-sm" placeholder="you@example.com" />
          </div>

          <div className="mb-4">
            <label className="block text-xs font-semibold uppercase tracking-wide text-stone-500 mb-1">Password</label>
            <div className="relative">
              <Lock size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
              <input type="password" value={password} onChange={e => setPassword(e.target.value)} required
                className="w-full pl-9 pr-3 py-2 rounded-lg border border-stone-300 text-sm" placeholder="Enter password" />
            </div>
          </div>

          {error && <p className="text-xs text-red-600 mb-3">{error}</p>}

          <button type="submit" disabled={checking} className="w-full py-2.5 rounded-lg text-white text-sm font-semibold disabled:opacity-60" style={{ background: NAVY }}>
            {checking ? "Signing in…" : "Log In"}
          </button>
        </form>
      </div>
    </div>
  );
}

// ---------- MAIN APP (post-login) ----------

function MainApp({ session, onLogout }) {
  const isAdmin = session.role === "admin";
  const [members, setMembers] = useState([]);
  const [officials, setOfficials] = useState([]);
  const [loading, setLoading] = useState(true);
  const [view, setView] = useState("dashboard");
  const [scopeBarangay, setScopeBarangay] = useState(isAdmin ? "All Barangays" : session.barangay);
  const [search, setSearch] = useState("");
  const [filterBarangay, setFilterBarangay] = useState("All Barangays");
  const [filterClass, setFilterClass] = useState("All");
  const [showArchived, setShowArchived] = useState(false);
  const [form, setForm] = useState({ ...emptyMemberForm, barangay: isAdmin ? BARANGAYS[0] : session.barangay });
  const [editingId, setEditingId] = useState(null);
  const [officialForm, setOfficialForm] = useState({ ...emptyOfficialForm, barangay: isAdmin ? BARANGAYS[0] : session.barangay });
  const [editingOfficialId, setEditingOfficialId] = useState(null);
  const [toast, setToast] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [confirmArchive, setConfirmArchive] = useState(null);
  const [confirmDeleteOfficial, setConfirmDeleteOfficial] = useState(null);
  const [confirmReject, setConfirmReject] = useState(null);
  const [saveError, setSaveError] = useState("");
  const [loadError, setLoadError] = useState(false);
  const [loadErrorDetail, setLoadErrorDetail] = useState("");

  useEffect(() => { loadAll(); }, []);

  async function loadAll() {
    setLoading(true);
    try {
      const [m, o] = await Promise.all([storage.getMembers(), storage.getOfficials()]);
      setMembers(m);
      setOfficials(o);
      setLoadError(false);
      setLoadErrorDetail("");
    } catch (e) {
      setMembers([]); setOfficials([]);
      setLoadError(true);
      setLoadErrorDetail((e && (e.message || e.toString())) || "Unknown error");
    }
    setLoading(false);
  }

  function showToast(msg) { setToast(msg); setTimeout(() => setToast(""), 2200); }

  function resetMemberForm() {
    setForm({ ...emptyMemberForm, barangay: isAdmin ? (scopeBarangay !== "All Barangays" ? scopeBarangay : BARANGAYS[0]) : session.barangay });
    setEditingId(null);
  }
  function resetOfficialForm() {
    setOfficialForm({ ...emptyOfficialForm, barangay: isAdmin ? (scopeBarangay !== "All Barangays" ? scopeBarangay : BARANGAYS[0]) : session.barangay });
    setEditingOfficialId(null);
  }

  function startEditMember(m) { setForm({ ...m }); setEditingId(m.id); setView("add"); }
  function startEditOfficial(o) { setOfficialForm({ ...o }); setEditingOfficialId(o.id); setView("addOfficial"); }

  function toggleClassification(c) {
    setForm(f => {
      const has = f.classification.includes(c);
      const classification = has ? f.classification.filter(x => x !== c) : [...f.classification, c];
      const stillISY = classification.some(x => x.includes("In-School Youth"));
      return { ...f, classification, schoolName: stillISY ? f.schoolName : "", gradeLevel: stillISY ? f.gradeLevel : "", program: stillISY ? f.program : "" };
    });
  }

  // Each of these now talks to one row directly — the database's row-level
  // security (not this code) is what actually stops an officer from
  // touching another barangay's data, so there's no more read-modify-write
  // of a whole shared list, and no more conflict-retry logic needed: two
  // people editing different rows simply can't collide anymore.
  // Flags a likely duplicate: same first + last name and same birthdate,
  // ignoring an archived record or the one currently being edited. This is
  // a soft warning, not a hard block — staff can still save if it's a
  // genuine coincidence (e.g. cousins with the same name).
  function findDuplicateMember(candidate, excludeId) {
    const norm = s => (s || "").trim().toLowerCase();
    return members.find(m =>
      m.id !== excludeId &&
      !m.archived &&
      norm(m.lastName) === norm(candidate.lastName) &&
      norm(m.firstName) === norm(candidate.firstName) &&
      (m.birthdate || "") === (candidate.birthdate || "")
    );
  }

  async function handleMemberSubmit(e) {
    e.preventDefault();
    if (!form.lastName.trim() || !form.firstName.trim()) { showToast("Last name and first name are required."); return; }
    if (!isAdmin && form.barangay !== session.barangay) { showToast("You can only add members for your own barangay."); return; }
    const age = calcAge(form.birthdate);
    const record = { ...form, age, ageGroup: ageGroupFromAge(age), verified: true, source: form.source || "staff" };
    const dupe = findDuplicateMember(record, editingId);
    if (dupe) {
      const proceed = window.confirm(
        `A member named ${record.firstName} ${record.lastName} with the same birthdate is already recorded (Brgy. ${dupe.barangay}). Save this one anyway?`
      );
      if (!proceed) return;
    }
    try {
      if (editingId) {
        const updated = await storage.updateMember(editingId, record);
        setMembers(current => current.map(m => m.id === editingId ? updated : m));
        showToast("Member record updated.");
      } else {
        const created = await storage.addMember(record);
        setMembers(current => [...current, created]);
        showToast("Member added to the profile.");
      }
      setSaveError("");
      resetMemberForm();
      setView("members");
    } catch (e2) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }

  async function handleOfficialSubmit(e) {
    e.preventDefault();
    if (!officialForm.lastName.trim() || !officialForm.firstName.trim()) { showToast("Last name and first name are required."); return; }
    if (!isAdmin && officialForm.barangay !== session.barangay) { showToast("You can only add officials for your own barangay."); return; }
    try {
      if (editingOfficialId) {
        const updated = await storage.updateOfficial(editingOfficialId, officialForm);
        setOfficials(current => current.map(o => o.id === editingOfficialId ? updated : o));
        showToast("Official record updated.");
      } else {
        const created = await storage.addOfficial(officialForm);
        setOfficials(current => [...current, created]);
        showToast("SK official added.");
      }
      setSaveError("");
      resetOfficialForm();
      setView("officials");
    } catch (e2) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }

  async function handleDeleteMember(id) {
    try {
      await storage.deleteMember(id);
      setMembers(current => current.filter(m => m.id !== id));
      setConfirmDelete(null);
      showToast("Record removed.");
    } catch (e) {
      setSaveError("Could not delete — please check your connection and try again.");
    }
  }
  async function handleArchiveMember(id) {
    try {
      const updated = await storage.updateMember(id, { ...members.find(m => m.id === id), archived: true });
      setMembers(current => current.map(m => m.id === id ? updated : m));
      setConfirmArchive(null);
      showToast("Member archived (removed from active KK roll).");
    } catch (e) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }
  async function handleUnarchiveMember(id) {
    try {
      const updated = await storage.updateMember(id, { ...members.find(m => m.id === id), archived: false });
      setMembers(current => current.map(m => m.id === id ? updated : m));
      showToast("Member restored to active roll.");
    } catch (e) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }
  async function handleDeleteOfficial(id) {
    try {
      await storage.deleteOfficial(id);
      setOfficials(current => current.filter(o => o.id !== id));
      setConfirmDeleteOfficial(null);
      showToast("Official record removed.");
    } catch (e) {
      setSaveError("Could not delete — please check your connection and try again.");
    }
  }

  async function handleApprove(id) {
    try {
      const updated = await storage.updateMember(id, { ...members.find(m => m.id === id), verified: true });
      setMembers(current => current.map(m => m.id === id ? updated : m));
      showToast("Member verified and added to the active roll.");
    } catch (e) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }
  async function handleReject(id) {
    try {
      await storage.deleteMember(id);
      setMembers(current => current.filter(m => m.id !== id));
      setConfirmReject(null);
      showToast("Submission rejected and removed.");
    } catch (e) {
      setSaveError("Could not save — please check your connection and try again.");
    }
  }

  const filteredMembers = useMemo(() => {
    return members.filter(m => {
      if (!m.verified) return false;
      if (!!m.archived !== showArchived) return false;
      if (scopeBarangay !== "All Barangays" && m.barangay !== scopeBarangay) return false;
      if (filterBarangay !== "All Barangays" && m.barangay !== filterBarangay) return false;
      if (filterClass !== "All" && !(m.classification || []).includes(filterClass)) return false;
      if (search.trim()) {
        const q = search.toLowerCase();
        const full = `${m.lastName} ${m.firstName} ${m.middleName}`.toLowerCase();
        if (!full.includes(q)) return false;
      }
      return true;
    }).sort((a, b) => (a.lastName || "").localeCompare(b.lastName || ""));
  }, [members, scopeBarangay, filterBarangay, filterClass, search, showArchived]);

  const pendingMembers = useMemo(() => {
    return members.filter(m => !m.verified && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay))
      .sort((a, b) => (a.lastName || "").localeCompare(b.lastName || ""));
  }, [members, scopeBarangay]);

  const filteredOfficials = useMemo(() => {
    return officials.filter(o => scopeBarangay === "All Barangays" || o.barangay === scopeBarangay)
      .sort((a, b) => (a.barangay || "").localeCompare(b.barangay || "") || SK_POSITIONS.indexOf(a.position) - SK_POSITIONS.indexOf(b.position));
  }, [officials, scopeBarangay]);

  const scopedMembers = useMemo(
    () => members.filter(m => m.verified && !m.archived && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay)),
    [members, scopeBarangay]
  );

  const agingList = useMemo(
    () => scopedMembers.map(m => ({ ...m, aging: agingStatus(m) })).filter(m => m.aging).sort((a, b) => b.age - a.age),
    [scopedMembers]
  );

  const perBarangayData = useMemo(() => {
    return BARANGAYS.map(b => ({ name: b, count: members.filter(m => m.barangay === b && !m.archived && m.verified).length }))
      .filter(d => scopeBarangay === "All Barangays" || d.name === scopeBarangay);
  }, [members, scopeBarangay]);

  const ageGroupData = useMemo(() => AGE_GROUPS.map(g => ({ name: g.split(" (")[0], value: scopedMembers.filter(m => m.ageGroup === g).length })), [scopedMembers]);
  const classData = useMemo(() => CLASSIFICATIONS.map(c => ({ name: c.split(" (")[0], value: scopedMembers.filter(m => (m.classification || []).includes(c)).length })), [scopedMembers]);

  const pwdCount = scopedMembers.filter(m => m.pwd).length;
  const ipCount = scopedMembers.filter(m => m.ip).length;

  // filterBarangay (the Members-page dropdown) narrows further than
  // scopeBarangay (the admin's top-level scope), so it's the one that
  // reflects what's actually in filteredMembers when it's set.
  const effectiveScope = filterBarangay !== "All Barangays" ? filterBarangay : scopeBarangay;

  // The Reports page's own export, independent of Members-page filters.
  // Mirrors exactly what Reports' on-screen "Total active KK members"
  // count already computes — barangay scope only, nothing from the
  // Members tab's search/barangay/classification filters can silently
  // shrink this one.
  const reportScopedMembers = useMemo(
    () => members.filter(m => m.verified && !m.archived && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay)),
    [members, scopeBarangay]
  );

  function exportCSV() {
    const headers = ["Barangay","Last Name","First Name","Middle Name","Suffix","Age","Birthdate","Sex","Civil Status","Classification","School / Institution","Grade / Year Level","Program / Strand","PWD","IP","Age Group","Email","Contact","Address","Education","Work Status","Registered SK Voter","Registered National Voter","Attended KK Assembly","Archived","Source"];
    const rows = filteredMembers.map(m => [
      m.barangay, m.lastName, m.firstName, m.middleName, m.suffix, m.age, m.birthdate, m.sex, m.civilStatus,
      (m.classification || []).join("; "), m.schoolName || "", m.gradeLevel || "", m.program || "", m.pwd ? "Yes" : "No", m.ip ? "Yes" : "No", m.ageGroup,
      m.email, m.contact, m.address, m.education, m.workStatus, m.registeredSKVoter, m.registeredNationalVoter, m.attendedAssembly, m.archived ? "Yes" : "No", m.source || "staff"
    ]);
    downloadCSV(headers, rows, `KK-Profile-${effectiveScope.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.csv`);
  }

  // LGU-ready .xlsx export: one sheet with the full member roster (same
  // columns as the CSV export, plus School/Institution), and a second
  // "Summary" sheet with the per-barangay and per-classification counts —
  // the numbers a municipal youth office typically asks for, ready to
  // paste into a report without recomputing anything.
  function exportExcel() {
    const memberHeaders = ["Barangay","Last Name","First Name","Middle Name","Suffix","Age","Birthdate","Sex","Civil Status","Classification","School / Institution","Grade / Year Level","Program / Strand","PWD","IP","Age Group","Email","Contact","Address","Education","Work Status","Registered SK Voter","Registered National Voter","Attended KK Assembly","Archived","Source"];
    const memberRows = filteredMembers.map(m => [
      m.barangay, m.lastName, m.firstName, m.middleName, m.suffix, m.age, m.birthdate, m.sex, m.civilStatus,
      (m.classification || []).join("; "), m.schoolName || "", m.gradeLevel || "", m.program || "", m.pwd ? "Yes" : "No", m.ip ? "Yes" : "No", m.ageGroup,
      m.email, m.contact, m.address, m.education, m.workStatus, m.registeredSKVoter, m.registeredNationalVoter, m.attendedAssembly, m.archived ? "Yes" : "No", m.source || "staff"
    ]);
    const membersSheet = XLSX.utils.aoa_to_sheet([memberHeaders, ...memberRows]);
    membersSheet["!cols"] = memberHeaders.map(() => ({ wch: 16 }));

    const activeMembers = filteredMembers.filter(m => !m.archived);
    const summaryRows = [
      ["Ka-Par! — KK Profile Summary"],
      ["Scope", effectiveScope],
      ["Generated", new Date().toLocaleString("en-PH")],
      [],
      ["Total Active KK Members", activeMembers.length],
      ["PWD", activeMembers.filter(m => m.pwd).length],
      ["Indigenous Person (IP)", activeMembers.filter(m => m.ip).length],
      [],
      ["Per Barangay", "Count"],
      ...BARANGAYS
        .filter(b => effectiveScope === "All Barangays" || b === effectiveScope)
        .map(b => [b, activeMembers.filter(m => m.barangay === b).length]),
      [],
      ["Per Classification", "Count"],
      ...CLASSIFICATIONS.map(c => [c, activeMembers.filter(m => (m.classification || []).includes(c)).length]),
      [],
      ["Per Age Group", "Count"],
      ...AGE_GROUPS.map(g => [g, activeMembers.filter(m => m.ageGroup === g).length]),
    ];
    const summarySheet = XLSX.utils.aoa_to_sheet(summaryRows);
    summarySheet["!cols"] = [{ wch: 32 }, { wch: 14 }];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, membersSheet, "Full Member List");
    XLSX.utils.book_append_sheet(wb, summarySheet, "Summary");
    XLSX.writeFile(wb, `KK-Profile-${effectiveScope.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.xlsx`);
  }

  // Reports-page versions of the two exports above — same column layout,
  // but built from reportScopedMembers instead of filteredMembers, so a
  // forgotten search term or classification filter on the Members tab
  // can never silently shrink what Reports downloads.
  function exportReportCSV() {
    const headers = ["Barangay","Last Name","First Name","Middle Name","Suffix","Age","Birthdate","Sex","Civil Status","Classification","School / Institution","Grade / Year Level","Program / Strand","PWD","IP","Age Group","Email","Contact","Address","Education","Work Status","Registered SK Voter","Registered National Voter","Attended KK Assembly","Archived","Source"];
    const rows = reportScopedMembers.map(m => [
      m.barangay, m.lastName, m.firstName, m.middleName, m.suffix, m.age, m.birthdate, m.sex, m.civilStatus,
      (m.classification || []).join("; "), m.schoolName || "", m.gradeLevel || "", m.program || "", m.pwd ? "Yes" : "No", m.ip ? "Yes" : "No", m.ageGroup,
      m.email, m.contact, m.address, m.education, m.workStatus, m.registeredSKVoter, m.registeredNationalVoter, m.attendedAssembly, m.archived ? "Yes" : "No", m.source || "staff"
    ]);
    downloadCSV(headers, rows, `KK-Profile-${scopeBarangay.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.csv`);
  }

  function exportReportExcel() {
    const memberHeaders = ["Barangay","Last Name","First Name","Middle Name","Suffix","Age","Birthdate","Sex","Civil Status","Classification","School / Institution","Grade / Year Level","Program / Strand","PWD","IP","Age Group","Email","Contact","Address","Education","Work Status","Registered SK Voter","Registered National Voter","Attended KK Assembly","Archived","Source"];
    const memberRows = reportScopedMembers.map(m => [
      m.barangay, m.lastName, m.firstName, m.middleName, m.suffix, m.age, m.birthdate, m.sex, m.civilStatus,
      (m.classification || []).join("; "), m.schoolName || "", m.gradeLevel || "", m.program || "", m.pwd ? "Yes" : "No", m.ip ? "Yes" : "No", m.ageGroup,
      m.email, m.contact, m.address, m.education, m.workStatus, m.registeredSKVoter, m.registeredNationalVoter, m.attendedAssembly, m.archived ? "Yes" : "No", m.source || "staff"
    ]);
    const membersSheet = XLSX.utils.aoa_to_sheet([memberHeaders, ...memberRows]);
    membersSheet["!cols"] = memberHeaders.map(() => ({ wch: 16 }));

    const summaryRows = [
      ["Ka-Par! — KK Profile Summary"],
      ["Scope", scopeBarangay],
      ["Generated", new Date().toLocaleString("en-PH")],
      [],
      ["Total Active KK Members", reportScopedMembers.length],
      ["PWD", reportScopedMembers.filter(m => m.pwd).length],
      ["Indigenous Person (IP)", reportScopedMembers.filter(m => m.ip).length],
      [],
      ["Per Barangay", "Count"],
      ...BARANGAYS
        .filter(b => scopeBarangay === "All Barangays" || b === scopeBarangay)
        .map(b => [b, reportScopedMembers.filter(m => m.barangay === b).length]),
      [],
      ["Per Classification", "Count"],
      ...CLASSIFICATIONS.map(c => [c, reportScopedMembers.filter(m => (m.classification || []).includes(c)).length]),
      [],
      ["Per Age Group", "Count"],
      ...AGE_GROUPS.map(g => [g, reportScopedMembers.filter(m => m.ageGroup === g).length]),
    ];
    const summarySheet = XLSX.utils.aoa_to_sheet(summaryRows);
    summarySheet["!cols"] = [{ wch: 32 }, { wch: 14 }];

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, membersSheet, "Full Member List");
    XLSX.utils.book_append_sheet(wb, summarySheet, "Summary");
    XLSX.writeFile(wb, `KK-Profile-${scopeBarangay.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.xlsx`);
  }

  function exportOfficialsCSV() {
    const headers = ["Barangay", "Position", "Last Name", "First Name", "Middle Name", "Term Start", "Term End", "Contact", "Email"];
    const rows = filteredOfficials.map(o => [o.barangay, o.position, o.lastName, o.firstName, o.middleName, o.termStart, o.termEnd, o.contact, o.email]);
    downloadCSV(headers, rows, `SK-Officials-${scopeBarangay.replace(/\s+/g, "_")}-${new Date().toISOString().slice(0,10)}.csv`);
  }

  function downloadCSV(headers, rows, filename) {
    const csv = [headers, ...rows].map(r => r.map(v => `"${String(v ?? "").replace(/"/g, '""')}"`).join(",")).join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url; a.download = filename; a.click();
    URL.revokeObjectURL(url);
  }

  const inputCls = "w-full rounded-lg border border-stone-300 bg-white px-3 py-2 text-sm text-stone-800 focus:outline-none focus:ring-2 focus:ring-[#E8A93B] focus:border-transparent";
  const labelCls = "block text-xs font-semibold uppercase tracking-wide text-stone-500 mb-1";

  const navItems = [
    { id: "dashboard", label: "Dashboard", icon: LayoutDashboard },
    { id: "pending", label: "Pending", icon: ClipboardCheck, badge: pendingMembers.length },
    { id: "members", label: "Members", icon: Users },
    { id: "add", label: "Add Member", icon: Plus },
    { id: "officials", label: "SK Officials", icon: ShieldCheck },
    { id: "reports", label: "Reports", icon: FileBarChart },
    { id: "settings", label: "Settings", icon: SettingsIcon },
  ];

  return (
    <div className="min-h-screen" style={{ background: CREAM, fontFamily: "'Inter', system-ui, sans-serif" }}>
      <header className="text-white" style={{ background: NAVY }}>
        <div className="max-w-6xl mx-auto px-5 py-4 flex items-center gap-4">
          <LogoBadge src={PYD_LOGO_B64} label="Presentacion Youth Development / NYC" size={48} />
          <div className="min-w-0 flex-1">
            <h1 className="text-base sm:text-lg font-bold leading-tight truncate">Ka-Par! <span className="font-normal text-blue-100">&middot; Alamin. Iprofile. Paunlarin.</span></h1>
            <p className="text-[11px] sm:text-xs text-blue-100 truncate">
              {isAdmin ? "PYDO Admin" : `SK Officer — Brgy. ${session.barangay}`} &middot; Municipality of Presentacion
            </p>
          </div>
          <button onClick={onLogout} className="flex items-center gap-1 text-xs text-blue-100 hover:text-white shrink-0">
            <LogOut size={14} /> <span className="hidden sm:inline">Log out</span>
          </button>
        </div>
        <nav className="max-w-6xl mx-auto px-5 flex gap-1 overflow-x-auto pb-2">
          {navItems.map(t => (
            <button key={t.id}
              onClick={() => { if (t.id === "add") resetMemberForm(); if (t.id === "addOfficial") resetOfficialForm(); setView(t.id); }}
              className="relative flex items-center gap-1.5 px-3 py-1.5 rounded-t-lg text-xs sm:text-sm font-medium whitespace-nowrap transition"
              style={view === t.id ? { background: CREAM, color: NAVY } : { background: "rgba(255,255,255,0.08)", color: "#E5E1D8" }}>
              <t.icon size={15} /> {t.label}
              {!!t.badge && <span className="ml-1 text-[10px] font-bold rounded-full px-1.5 py-0.5" style={{ background: RUST, color: "white" }}>{t.badge}</span>}
            </button>
          ))}
        </nav>
      </header>

      <div className="border-b border-stone-200 bg-white">
        <div className="max-w-6xl mx-auto px-5 py-2.5 flex flex-wrap items-center gap-2 text-sm">
          <MapPin size={15} style={{ color: LEAF }} />
          <span className="text-stone-500 text-xs sm:text-sm">Viewing:</span>
          {isAdmin ? (
            <div className="relative">
              <select value={scopeBarangay} onChange={e => setScopeBarangay(e.target.value)}
                className="appearance-none bg-stone-100 border border-stone-300 rounded-lg pl-3 pr-7 py-1 text-xs sm:text-sm font-semibold text-stone-800">
                <option>All Barangays</option>
                {BARANGAYS.map(b => <option key={b}>{b}</option>)}
              </select>
              <ChevronDown size={13} className="absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-stone-500" />
            </div>
          ) : (
            <span className="bg-stone-100 border border-stone-300 rounded-lg px-3 py-1 text-xs sm:text-sm font-semibold text-stone-800">{session.barangay}</span>
          )}
          <span className="ml-auto text-xs text-stone-400">{scopedMembers.length} active KK member{scopedMembers.length === 1 ? "" : "s"}</span>
          {agingList.length > 0 && (
            <button onClick={() => setView("dashboard")} className="flex items-center gap-1 text-xs font-medium px-2 py-1 rounded-full" style={{ background: "#FCEFE0", color: RUST }}>
              <AlertTriangle size={12} /> {agingList.length} aging out
            </button>
          )}
        </div>
      </div>

      <main className="max-w-6xl mx-auto px-5 py-6">
        {loadError && (
          <div className="mb-4 text-sm text-amber-800 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
            Could not connect to the database. Records shown below may be out of date, and anything you add or edit
            right now will not be saved. Check your internet connection and reload the page — if this keeps
            happening, the site's Supabase configuration may need to be checked.
            {loadErrorDetail && <div className="mt-1 font-mono text-xs opacity-80">Details: {loadErrorDetail}</div>}
          </div>
        )}
        {saveError && <div className="mb-4 text-sm text-red-700 bg-red-50 border border-red-200 rounded-lg px-3 py-2">{saveError}</div>}

        {loading ? (
          <div className="text-center text-stone-400 py-20 text-sm">Loading profile data…</div>
        ) : view === "dashboard" ? (
          <Dashboard scopeBarangay={scopeBarangay} scopedMembers={scopedMembers} perBarangayData={perBarangayData}
            ageGroupData={ageGroupData} classData={classData} pwdCount={pwdCount} ipCount={ipCount}
            agingList={agingList} onArchive={id => setConfirmArchive(id)} pendingCount={pendingMembers.length}
            onViewPending={() => setView("pending")} isAdmin={isAdmin} />
        ) : view === "pending" ? (
          <PendingQueue pendingMembers={pendingMembers} onApprove={handleApprove}
            onReject={id => setConfirmReject(id)} onEdit={startEditMember} />
        ) : view === "members" ? (
          <MembersList search={search} setSearch={setSearch} filterBarangay={filterBarangay} setFilterBarangay={setFilterBarangay}
            filterClass={filterClass} setFilterClass={setFilterClass} filteredMembers={filteredMembers}
            startEdit={startEditMember} confirmDelete={confirmDelete} setConfirmDelete={setConfirmDelete}
            handleDelete={handleDeleteMember} exportCSV={exportCSV} exportExcel={exportExcel} isAdmin={isAdmin}
            showArchived={showArchived} setShowArchived={setShowArchived}
            onArchive={id => setConfirmArchive(id)} onUnarchive={handleUnarchiveMember} />
        ) : view === "add" ? (
          <MemberForm form={form} setForm={setForm} editingId={editingId} handleSubmit={handleMemberSubmit}
            toggleClassification={toggleClassification} resetForm={resetMemberForm} setView={setView}
            inputCls={inputCls} labelCls={labelCls} isAdmin={isAdmin} lockedBarangay={session.barangay} />
        ) : view === "officials" ? (
          <OfficialsList officials={filteredOfficials} startEdit={startEditOfficial}
            confirmDelete={confirmDeleteOfficial} setConfirmDelete={setConfirmDeleteOfficial}
            handleDelete={handleDeleteOfficial} exportCSV={exportOfficialsCSV} setView={setView} resetForm={resetOfficialForm} />
        ) : view === "addOfficial" ? (
          <OfficialForm form={officialForm} setForm={setOfficialForm} editingId={editingOfficialId}
            handleSubmit={handleOfficialSubmit} resetForm={resetOfficialForm} setView={setView}
            inputCls={inputCls} labelCls={labelCls} isAdmin={isAdmin} lockedBarangay={session.barangay} />
        ) : view === "settings" ? (
          <SettingsPanel session={session} showToast={showToast} members={members} officials={officials} />
        ) : (
          <Reports scopeBarangay={scopeBarangay} members={members} agingList={agingList} exportCSV={exportReportCSV} exportExcel={exportReportExcel} />
        )}
      </main>

      {toast && <div className="fixed bottom-5 left-1/2 -translate-x-1/2 bg-stone-900 text-white text-sm px-4 py-2 rounded-full shadow-lg z-50">{toast}</div>}

      {confirmArchive && (
        <ConfirmModal
          text="Archive this member? They'll be removed from the active KK roll and counts, but the record is kept for records/history."
          confirmLabel="Archive" confirmClass="bg-amber-600"
          onCancel={() => setConfirmArchive(null)} onConfirm={() => handleArchiveMember(confirmArchive)} />
      )}
      {confirmReject && (
        <ConfirmModal
          text="Reject and permanently delete this self-submitted profile? This cannot be undone."
          confirmLabel="Reject & Delete" confirmClass="bg-red-600"
          onCancel={() => setConfirmReject(null)} onConfirm={() => handleReject(confirmReject)} />
      )}
    </div>
  );
}

function ConfirmModal({ text, confirmLabel, confirmClass, onCancel, onConfirm }) {
  return (
    <div className="fixed inset-0 bg-black/40 flex items-center justify-center z-50 px-4" onClick={onCancel}>
      <div className="bg-white rounded-xl p-5 max-w-sm w-full" onClick={e => e.stopPropagation()}>
        <p className="text-sm text-stone-700 mb-4">{text}</p>
        <div className="flex gap-2 justify-end">
          <button onClick={onCancel} className="px-3 py-1.5 rounded-lg text-sm text-stone-600 border border-stone-300">Cancel</button>
          <button onClick={onConfirm} className={`px-3 py-1.5 rounded-lg text-sm text-white ${confirmClass}`}>{confirmLabel}</button>
        </div>
      </div>
    </div>
  );
}

function StatCard({ label, value, accent }) {
  return (
    <div className="bg-white rounded-xl border border-stone-200 p-4">
      <p className="text-xs font-semibold uppercase tracking-wide text-stone-400">{label}</p>
      <p className="text-2xl font-bold mt-1" style={{ color: accent || NAVY }}>{value}</p>
    </div>
  );
}

function Dashboard({ scopeBarangay, scopedMembers, perBarangayData, ageGroupData, classData, pwdCount, ipCount, agingList, onArchive, pendingCount, onViewPending, isAdmin }) {
  return (
    <div className="space-y-6">
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <StatCard label="Active KK Members" value={scopedMembers.length} />
        <StatCard label="Barangays Covered" value={scopeBarangay === "All Barangays" ? 18 : 1} accent={LEAF} />
        <StatCard label="PWD" value={pwdCount} accent={GOLD} />
        <StatCard label="Indigenous Peoples" value={ipCount} accent={RUST} />
      </div>

      {pendingCount > 0 && (
        <button onClick={onViewPending} className="w-full flex items-center justify-between bg-white rounded-xl border p-4 text-left" style={{ borderColor: "#F3D9B1" }}>
          <div className="flex items-center gap-3">
            <ClipboardCheck size={20} style={{ color: GOLD }} />
            <div>
              <p className="text-sm font-semibold" style={{ color: NAVY }}>{pendingCount} self-submitted profile{pendingCount === 1 ? "" : "s"} awaiting verification</p>
              <p className="text-xs text-stone-500">{isAdmin ? "Across your selected scope" : "For your barangay"} — review before they count in the official roll.</p>
            </div>
          </div>
          <span className="text-xs font-semibold" style={{ color: GOLD }}>Review →</span>
        </button>
      )}

      {agingList.length > 0 && (
        <div className="bg-white rounded-xl border p-4" style={{ borderColor: "#F3D9B1" }}>
          <h3 className="text-sm font-bold text-stone-700 mb-3 flex items-center gap-2"><AlertTriangle size={15} style={{ color: RUST }} /> Aging-Out Alerts</h3>
          <div className="space-y-2">
            {agingList.slice(0, 8).map(m => (
              <div key={m.id} className="flex items-center justify-between text-sm border-b border-stone-100 pb-2 last:border-0">
                <div>
                  <span className="font-medium">{m.lastName}, {m.firstName}</span>
                  <span className="text-stone-400 text-xs ml-2">{m.barangay} &middot; Age {m.age}</span>
                  <p className="text-xs" style={{ color: m.aging.level === "overage" ? RUST : m.aging.level === "urgent" ? GOLD : "#78716c" }}>{m.aging.label}</p>
                </div>
                {m.aging.level === "overage" && (
                  <button onClick={() => onArchive(m.id)} className="flex items-center gap-1 text-xs font-medium px-2 py-1 rounded-lg border" style={{ borderColor: RUST, color: RUST }}>
                    <Archive size={12} /> Archive
                  </button>
                )}
              </div>
            ))}
            {agingList.length > 8 && <p className="text-xs text-stone-400 pt-1">+{agingList.length - 8} more — see Reports for the full list.</p>}
          </div>
        </div>
      )}

      {scopeBarangay === "All Barangays" && (
        <div className="bg-white rounded-xl border border-stone-200 p-4">
          <h3 className="text-sm font-bold text-stone-700 mb-3">KK Members per Barangay</h3>
          <div style={{ width: "100%", height: 320 }}>
            <ResponsiveContainer>
              <BarChart data={perBarangayData} margin={{ top: 5, right: 10, left: -20, bottom: 60 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                <XAxis dataKey="name" angle={-45} textAnchor="end" interval={0} height={80} tick={{ fontSize: 10 }} />
                <YAxis allowDecimals={false} tick={{ fontSize: 11 }} />
                <Tooltip />
                <Bar dataKey="count" fill={NAVY} radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      )}

      <div className="grid sm:grid-cols-2 gap-4">
        <div className="bg-white rounded-xl border border-stone-200 p-4">
          <h3 className="text-sm font-bold text-stone-700 mb-3">By Age Group</h3>
          <div style={{ width: "100%", height: 240 }}>
            <ResponsiveContainer>
              <PieChart>
                <Pie data={ageGroupData} dataKey="value" nameKey="name" outerRadius={80} label={{ fontSize: 11 }}>
                  {ageGroupData.map((_, i) => <Cell key={i} fill={PIE_COLORS[i % PIE_COLORS.length]} />)}
                </Pie>
                <Legend wrapperStyle={{ fontSize: 11 }} />
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
        <div className="bg-white rounded-xl border border-stone-200 p-4">
          <h3 className="text-sm font-bold text-stone-700 mb-3">By Youth Classification</h3>
          <div style={{ width: "100%", height: 240 }}>
            <ResponsiveContainer>
              <BarChart data={classData} layout="vertical" margin={{ left: 10 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
                <XAxis type="number" allowDecimals={false} tick={{ fontSize: 11 }} />
                <YAxis type="category" dataKey="name" width={110} tick={{ fontSize: 10 }} />
                <Tooltip />
                <Bar dataKey="value" fill={LEAF} radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
}

function PendingQueue({ pendingMembers, onApprove, onReject, onEdit }) {
  if (pendingMembers.length === 0) {
    return <div className="text-center py-16 text-stone-400 text-sm bg-white rounded-xl border border-stone-200">No pending self-submitted profiles right now.</div>;
  }
  return (
    <div className="space-y-3">
      <h2 className="text-base font-bold" style={{ color: NAVY }}>Pending Verification</h2>
      {pendingMembers.map(m => (
        <div key={m.id} className="bg-white rounded-xl border border-stone-200 p-4 flex flex-col sm:flex-row sm:items-center gap-3 justify-between">
          <div>
            <p className="font-semibold text-sm">{m.lastName}, {m.firstName} {m.middleName}</p>
            <p className="text-xs text-stone-500">{m.barangay} &middot; Age {m.age} &middot; {m.contact || "no contact given"}</p>
            <p className="text-xs text-stone-400">{(m.classification || []).map(c => c.split(" (")[0]).join(", ") || "No classification given"}</p>
          </div>
          <div className="flex gap-2 shrink-0">
            <button onClick={() => onEdit(m)} className="px-3 py-1.5 rounded-lg text-xs font-medium border" style={{ borderColor: "#d6d3d1", color: "#57534e" }}>Review / Edit</button>
            <button onClick={() => onApprove(m.id)} className="px-3 py-1.5 rounded-lg text-xs font-medium text-white" style={{ background: LEAF }}>Approve</button>
            <button onClick={() => onReject(m.id)} className="px-3 py-1.5 rounded-lg text-xs font-medium text-white bg-red-600">Reject</button>
          </div>
        </div>
      ))}
    </div>
  );
}

function MembersList({ search, setSearch, filterBarangay, setFilterBarangay, filterClass, setFilterClass, filteredMembers, startEdit, confirmDelete, setConfirmDelete, handleDelete, exportCSV, exportExcel, isAdmin, showArchived, setShowArchived, onArchive, onUnarchive }) {
  return (
    <div>
      <div className="flex flex-col sm:flex-row gap-2 mb-4">
        <div className="relative flex-1">
          <Search size={15} className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-400" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search by name…"
            className="w-full pl-9 pr-3 py-2 rounded-lg border border-stone-300 text-sm focus:outline-none focus:ring-2" />
        </div>
        {isAdmin && (
          <select value={filterBarangay} onChange={e => setFilterBarangay(e.target.value)} className="rounded-lg border border-stone-300 px-3 py-2 text-sm">
            <option>All Barangays</option>
            {BARANGAYS.map(b => <option key={b}>{b}</option>)}
          </select>
        )}
        <select value={filterClass} onChange={e => setFilterClass(e.target.value)} className="rounded-lg border border-stone-300 px-3 py-2 text-sm">
          <option value="All">All Classifications</option>
          {CLASSIFICATIONS.map(c => <option key={c}>{c}</option>)}
        </select>
        <button onClick={() => setShowArchived(a => !a)} className="flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium border"
          style={showArchived ? { background: NAVY, color: "white", borderColor: NAVY } : { background: "white", color: "#57534e", borderColor: "#d6d3d1" }}>
          <Archive size={14} /> {showArchived ? "Archived" : "Active"}
        </button>
        <button onClick={exportCSV} className="flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium border" style={{ color: NAVY, borderColor: NAVY }}>
          <Download size={14} /> CSV
        </button>
        <button onClick={exportExcel} className="flex items-center justify-center gap-1.5 px-3 py-2 rounded-lg text-white text-sm font-medium" style={{ background: NAVY }}>
          <Download size={14} /> Excel
        </button>
      </div>

      {filteredMembers.length === 0 ? (
        <div className="text-center py-16 text-stone-400 text-sm bg-white rounded-xl border border-stone-200">
          {showArchived ? "No archived members." : "No verified KK members match this view yet."}
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-stone-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead style={{ background: NAVY }} className="text-white">
                <tr>
                  <th className="text-left px-3 py-2 font-semibold">KK ID</th>
                  <th className="text-left px-3 py-2 font-semibold">Name</th>
                  <th className="text-left px-3 py-2 font-semibold">Barangay</th>
                  <th className="text-left px-3 py-2 font-semibold">Age</th>
                  <th className="text-left px-3 py-2 font-semibold hidden sm:table-cell">Classification</th>
                  <th className="text-left px-3 py-2 font-semibold hidden md:table-cell">Contact</th>
                  <th className="px-3 py-2"></th>
                </tr>
              </thead>
              <tbody>
                {filteredMembers.map((m, i) => (
                  <tr key={m.id} className={i % 2 ? "bg-stone-50" : ""}>
                    <td className="px-3 py-2 whitespace-nowrap text-stone-500 text-xs font-mono">{m.memberId || "—"}</td>
                    <td className="px-3 py-2 whitespace-nowrap">{m.lastName}, {m.firstName} {m.middleName ? m.middleName[0] + "." : ""}</td>
                    <td className="px-3 py-2 text-stone-600 whitespace-nowrap">{m.barangay}</td>
                    <td className="px-3 py-2">{m.age}</td>
                    <td className="px-3 py-2 hidden sm:table-cell text-stone-500 text-xs">{(m.classification || []).map(c => c.split(" (")[0]).join(", ") || "—"}</td>
                    <td className="px-3 py-2 hidden md:table-cell text-stone-500 text-xs">{m.contact || "—"}</td>
                    <td className="px-3 py-2">
                      <div className="flex gap-2 justify-end">
                        {showArchived ? (
                          <button onClick={() => onUnarchive(m.id)} className="text-xs font-medium" style={{ color: LEAF }}>Restore</button>
                        ) : (
                          <>
                            {m.memberId && (
                              <a href={`/id/${m.id}`} target="_blank" rel="noopener noreferrer"
                                className="text-stone-500 hover:text-[#0038A8]" title="View / print digital ID">
                                <CreditCard size={15} />
                              </a>
                            )}
                            <button onClick={() => startEdit(m)} className="text-stone-500 hover:text-[#132A46]"><Pencil size={15} /></button>
                            <button onClick={() => onArchive(m.id)} className="text-stone-500 hover:text-amber-600"><Archive size={15} /></button>
                            <button onClick={() => setConfirmDelete(m.id)} className="text-stone-500 hover:text-red-600"><Trash2 size={15} /></button>
                          </>
                        )}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {confirmDelete && (
        <ConfirmModal text="Permanently remove this KK member record? This cannot be undone." confirmLabel="Delete" confirmClass="bg-red-600"
          onCancel={() => setConfirmDelete(null)} onConfirm={() => handleDelete(confirmDelete)} />
      )}
    </div>
  );
}

function MemberForm({ form, setForm, editingId, handleSubmit, toggleClassification, resetForm, setView, inputCls, labelCls, isAdmin, lockedBarangay }) {
  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState("");

  async function handlePhotoChange(e) {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setUploadError("");
    setUploading(true);
    try {
      const url = await storage.uploadMemberPhoto(form.barangay, file);
      setForm(f => ({ ...f, photoUrl: url }));
    } catch (err) {
      setUploadError("Could not upload photo — please try a smaller image.");
    }
    setUploading(false);
  }

  return (
    <form onSubmit={handleSubmit} className="bg-white rounded-xl border border-stone-200 p-5 max-w-3xl">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-base font-bold" style={{ color: NAVY }}>{editingId ? "Edit KK Member" : "Add KK Member"}</h2>
        <button type="button" onClick={() => { resetForm(); setView("members"); }} className="text-stone-400 hover:text-stone-600"><X size={18} /></button>
      </div>

      {form.source === "self" && !form.verified && (
        <div className="mb-4 text-xs px-3 py-2 rounded-lg" style={{ background: "#FCEFE0", color: RUST }}>
          This is a self-submitted profile awaiting verification. Saving here will mark it as verified.
        </div>
      )}

      {editingId && form.memberId && (
        <div className="mb-4 text-xs px-3 py-2 rounded-lg bg-stone-100 text-stone-600 font-mono">
          KK Member ID: <strong>{form.memberId}</strong>
        </div>
      )}

      <div className="mb-4 flex items-center gap-4">
        <div className="w-20 h-24 rounded-lg overflow-hidden bg-stone-100 shrink-0 flex items-center justify-center">
          {form.photoUrl
            ? <img src={form.photoUrl} alt="" className="w-full h-full object-cover" />
            : <Users size={24} className="text-stone-300" />}
        </div>
        <div>
          <label className={labelCls}>Photo (for the digital ID)</label>
          <input type="file" accept="image/jpeg,image/png,image/webp" onChange={handlePhotoChange} className="text-xs" />
          {uploading && <div className="text-xs text-stone-400 mt-1">Uploading…</div>}
          {uploadError && <div className="text-xs text-red-600 mt-1">{uploadError}</div>}
        </div>
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-4">
        <div>
          <label className={labelCls}>Barangay</label>
          {isAdmin ? (
            <select value={form.barangay} onChange={set("barangay")} className={inputCls}>{BARANGAYS.map(b => <option key={b}>{b}</option>)}</select>
          ) : (
            <input disabled value={lockedBarangay} className={inputCls + " bg-stone-100 text-stone-500"} />
          )}
        </div>
        <div>
          <label className={labelCls}>Sex Assigned at Birth</label>
          <select value={form.sex} onChange={set("sex")} className={inputCls}><option>Male</option><option>Female</option></select>
        </div>
      </div>

      <div className="grid sm:grid-cols-4 gap-4 mb-4">
        <div><label className={labelCls}>Last Name *</label><input required value={form.lastName} onChange={set("lastName")} className={inputCls} /></div>
        <div><label className={labelCls}>First Name *</label><input required value={form.firstName} onChange={set("firstName")} className={inputCls} /></div>
        <div><label className={labelCls}>Middle Name</label><input value={form.middleName} onChange={set("middleName")} className={inputCls} /></div>
        <div><label className={labelCls}>Suffix</label><input value={form.suffix} onChange={set("suffix")} className={inputCls} placeholder="Jr., III" /></div>
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-4">
        <div><label className={labelCls}>Birthdate</label><input type="date" value={form.birthdate} onChange={set("birthdate")} className={inputCls} /></div>
        <div>
          <label className={labelCls}>Civil Status</label>
          <select value={form.civilStatus} onChange={set("civilStatus")} className={inputCls}>{CIVIL_STATUS.map(c => <option key={c}>{c}</option>)}</select>
        </div>
      </div>

      <div className="mb-4">
        <label className={labelCls}>Youth Classification (select all that apply)</label>
        <div className="flex flex-wrap gap-2">
          {CLASSIFICATIONS.map(c => (
            <button type="button" key={c} onClick={() => toggleClassification(c)}
              className="px-3 py-1.5 rounded-full text-xs font-medium border transition"
              style={form.classification.includes(c) ? { background: NAVY, color: "white", borderColor: NAVY } : { background: "white", color: "#57534e", borderColor: "#d6d3d1" }}>
              {c}
            </button>
          ))}
        </div>
        <div className="flex gap-4 mt-2">
          <label className="flex items-center gap-1.5 text-sm text-stone-600"><input type="checkbox" checked={form.pwd} onChange={e => setForm(f => ({ ...f, pwd: e.target.checked }))} /> PWD</label>
          <label className="flex items-center gap-1.5 text-sm text-stone-600"><input type="checkbox" checked={form.ip} onChange={e => setForm(f => ({ ...f, ip: e.target.checked }))} /> Indigenous Person</label>
        </div>
        {form.classification.some(c => c.includes("In-School Youth")) && (
          <div className="mt-3 grid sm:grid-cols-2 gap-3">
            <div className="sm:col-span-2">
              <label className={labelCls}>School / Institution Name</label>
              <input value={form.schoolName} onChange={set("schoolName")} className={inputCls} placeholder="e.g. Presentacion National High School" list="school-options-admin" />
              <datalist id="school-options-admin">
                {SCHOOLS.map(s => <option key={s} value={s} />)}
              </datalist>
            </div>
            <div>
              <label className={labelCls}>Grade / Year Level</label>
              <select value={form.gradeLevel} className={inputCls}
                onChange={e => setForm(f => ({ ...f, gradeLevel: e.target.value, program: needsProgram(e.target.value) ? f.program : "" }))}>
                <option value="">Select…</option>
                {GRADE_LEVELS.map(g => <option key={g}>{g}</option>)}
              </select>
            </div>
            {needsProgram(form.gradeLevel) && (
              <div>
                <label className={labelCls}>{form.gradeLevel.includes("College") ? "Course / Program" : "Strand"}</label>
                <input value={form.program} onChange={set("program")} className={inputCls}
                  placeholder={form.gradeLevel.includes("College") ? "e.g. BS Computer Science" : "e.g. STEM, HUMSS, ABM"} />
              </div>
            )}
          </div>
        )}
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-4">
        <div><label className={labelCls}>Email Address</label><input type="email" value={form.email} onChange={set("email")} className={inputCls} /></div>
        <div><label className={labelCls}>Contact Number</label><input value={form.contact} onChange={set("contact")} className={inputCls} /></div>
      </div>

      <div className="mb-4">
        <label className={labelCls}>Home Address</label>
        <input value={form.address} onChange={set("address")} className={inputCls} placeholder="Purok/Sitio, Barangay" />
      </div>

      <div className="grid sm:grid-cols-2 gap-4 mb-4">
        <div>
          <label className={labelCls}>Highest Educational Attainment</label>
          <select value={form.education} onChange={set("education")} className={inputCls}>{EDUC_ATTAINMENT.map(e => <option key={e}>{e}</option>)}</select>
        </div>
        <div>
          <label className={labelCls}>Work Status</label>
          <select value={form.workStatus} onChange={set("workStatus")} className={inputCls}>{WORK_STATUS.map(w => <option key={w}>{w}</option>)}</select>
        </div>
      </div>

      <div className="grid sm:grid-cols-3 gap-4 mb-5">
        <div><label className={labelCls}>Registered SK Voter</label><select value={form.registeredSKVoter} onChange={set("registeredSKVoter")} className={inputCls}><option>Yes</option><option>No</option></select></div>
        <div><label className={labelCls}>Registered National Voter</label><select value={form.registeredNationalVoter} onChange={set("registeredNationalVoter")} className={inputCls}><option>Yes</option><option>No</option></select></div>
        <div><label className={labelCls}>Attended KK Assembly</label><select value={form.attendedAssembly} onChange={set("attendedAssembly")} className={inputCls}><option>Yes</option><option>No</option></select></div>
      </div>

      <div className="flex gap-2 justify-end">
        <button type="button" onClick={() => { resetForm(); setView("members"); }} className="px-4 py-2 rounded-lg text-sm text-stone-600 border border-stone-300">Cancel</button>
        <button type="submit" className="px-4 py-2 rounded-lg text-sm font-semibold text-white" style={{ background: NAVY }}>{editingId ? "Save & Verify" : "Add Member"}</button>
      </div>
    </form>
  );
}

