function SettingsPanel({ session, showToast, members, officials }) {
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [changing, setChanging] = useState(false);
  const [error, setError] = useState("");

  async function changeMyPassword() {
    setError("");
    if (newPassword.length < 8) { setError("Password must be at least 8 characters."); return; }
    if (newPassword !== confirmPassword) { setError("Passwords don't match."); return; }
    setChanging(true);
    try {
      await auth.changePassword(newPassword);
      showToast("Password updated.");
      setNewPassword(""); setConfirmPassword("");
    } catch (e) {
      setError("Could not update password. Please try again.");
    }
    setChanging(false);
  }

  return (
    <div className="max-w-2xl space-y-5">
      <div className="bg-white rounded-xl border border-stone-200 p-5">
        <h2 className="text-base font-bold mb-3 flex items-center gap-2" style={{ color: NAVY }}><Database size={16} /> Database Status</h2>
        <ul className="text-sm divide-y divide-stone-100">
          <li className="flex justify-between py-1.5"><span className="text-stone-600">KK member records (all barangays)</span><strong>{members.length}</strong></li>
          <li className="flex justify-between py-1.5"><span className="text-stone-600">SK official records</span><strong>{officials.length}</strong></li>
        </ul>
      </div>

      <div className="bg-white rounded-xl border border-stone-200 p-5">
        <h2 className="text-base font-bold mb-3" style={{ color: NAVY }}>Change My Password</h2>
        <p className="text-sm text-stone-500 mb-3">Signed in as {session.email || "this account"}.</p>
        <div className="space-y-2">
          <input type="password" placeholder="New password (min. 8 characters)" value={newPassword}
            onChange={e => setNewPassword(e.target.value)} className="w-full rounded-lg border border-stone-300 px-3 py-2 text-sm" />
          <input type="password" placeholder="Confirm new password" value={confirmPassword}
            onChange={e => setConfirmPassword(e.target.value)} className="w-full rounded-lg border border-stone-300 px-3 py-2 text-sm" />
          {error && <div className="text-sm text-red-700">{error}</div>}
          <button onClick={changeMyPassword} disabled={changing} className="px-4 py-2 rounded-lg text-sm font-semibold text-white disabled:opacity-60" style={{ background: NAVY }}>
            {changing ? "Saving…" : "Update Password"}
          </button>
        </div>
      </div>
    </div>
  );
}

function Reports({ scopeBarangay, members, agingList, exportCSV, exportExcel }) {
  const scoped = members.filter(m => m.verified && !m.archived && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay));
  const totalOSY = scoped.filter(m => (m.classification || []).some(c => c.includes("Out-of-School"))).length;
  const totalPWD = scoped.filter(m => m.pwd).length;
  const totalIP = scoped.filter(m => m.ip).length;
  const noAssembly = scoped.filter(m => m.attendedAssembly === "No").length;
  const unregistered = scoped.filter(m => m.registeredSKVoter === "No").length;
  const archivedCount = members.filter(m => m.archived && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay)).length;
  const pendingCount = members.filter(m => !m.verified && (scopeBarangay === "All Barangays" || m.barangay === scopeBarangay)).length;

  return (
    <div className="max-w-2xl space-y-5">
      <div className="bg-white rounded-xl border border-stone-200 p-5">
        <h2 className="text-base font-bold mb-1" style={{ color: NAVY }}>Summary Report</h2>
        <p className="text-xs text-stone-400 mb-4">Scope: {scopeBarangay} &middot; Generated {new Date().toLocaleDateString()}</p>
        <ul className="divide-y divide-stone-100 text-sm">
          <li className="flex justify-between py-2"><span>Total active KK members profiled</span><strong>{scoped.length}</strong></li>
          <li className="flex justify-between py-2"><span>Out-of-School Youth / NEET</span><strong>{totalOSY}</strong></li>
          <li className="flex justify-between py-2"><span>Persons with Disability</span><strong>{totalPWD}</strong></li>
          <li className="flex justify-between py-2"><span>Indigenous Peoples</span><strong>{totalIP}</strong></li>
          <li className="flex justify-between py-2"><span>Have not attended a KK Assembly</span><strong>{noAssembly}</strong></li>
          <li className="flex justify-between py-2"><span>Not registered as SK voter</span><strong>{unregistered}</strong></li>
          <li className="flex justify-between py-2"><span>Pending verification (self-submitted)</span><strong>{pendingCount}</strong></li>
          <li className="flex justify-between py-2"><span>Archived (removed from active roll)</span><strong>{archivedCount}</strong></li>
        </ul>
        <p className="text-xs text-stone-400 mt-3">
          Both downloads below include every member's full profile (name, contact, classification, school details, etc.) for everyone currently
          in view — not just the summary numbers above. The Excel file also includes this summary as a separate sheet.
        </p>
        <button onClick={exportExcel} className="mt-3 w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-white text-sm font-semibold" style={{ background: NAVY }}>
          <Download size={15} /> Download Full Member List (Excel) — for LGU/DILG submission
        </button>
        <button onClick={exportCSV} className="mt-2 w-full flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-semibold border" style={{ color: NAVY, borderColor: NAVY }}>
          <Download size={15} /> Download Full Member List (CSV)
        </button>
      </div>

      <div className="bg-white rounded-xl border border-stone-200 p-5">
        <h2 className="text-base font-bold mb-3 flex items-center gap-2" style={{ color: NAVY }}><AlertTriangle size={16} style={{ color: RUST }} /> Aging-Out Roster</h2>
        {agingList.length === 0 ? (
          <p className="text-sm text-stone-400">No members currently approaching the age-31 cutoff.</p>
        ) : (
          <ul className="divide-y divide-stone-100 text-sm">
            {agingList.map(m => (
              <li key={m.id} className="py-2 flex justify-between">
                <span>{m.lastName}, {m.firstName} — {m.barangay} (Age {m.age})</span>
                <span className="text-xs" style={{ color: m.aging.level === "overage" ? RUST : GOLD }}>{m.aging.label}</span>
              </li>
            ))}
          </ul>
        )}
      </div>

      <p className="text-[11px] text-stone-400">This data is stored for anyone with access to this system link — treat it per the Data Privacy Act of 2012 (RA 10173) and your barangay's consent forms.</p>
    </div>
  );
}
